// SendMessage: Sends a text message.
//
// Posts a text message into a chat the bot is in. A private chat needs the user's consent. With
// `random_id` a retry returns the first message instead of posting again (kept 7 days per bot;
// reusing it in another chat is an error).
func (c *Client) SendMessage(ctx context.Context, req SendMessageRequest) (*Message, error) {
	var out Message
	if err := c.call(ctx, "POST", "/messages", nil, req, &out); err != nil {
		return nil, err
	}
	return &out, nil
}

// EditMessage: Edits the text of one of the bot's messages.
//
// Replaces the text (the caption of a media message) and its entities; the message gets
// `edit_date` and users see "đã sửa". A `reply_markup` with an `inline_keyboard` replaces the
// keyboard; none keeps it (`messages:editMarkup` removes it). Bots edit their own messages at any
// age while they may still send in the chat; reply keyboards cannot be edited. Counts as a send.
func (c *Client) EditMessage(ctx context.Context, req EditMessageRequest) (*Message, error) {
	var out Message
	if err := c.call(ctx, "POST", "/messages:edit", nil, req, &out); err != nil {
		return nil, err
	}
	return &out, nil
}

// EditMessageMarkup: Replaces or removes the inline keyboard of one of the bot's messages.
//
// Without `reply_markup` the keyboard is removed. Changing only the keyboard is not an edit for
// users (no "đã sửa", no `message_edited`). Counts as a send.
func (c *Client) EditMessageMarkup(ctx context.Context, req EditMarkupRequest) (*Message, error) {
	var out Message
	if err := c.call(ctx, "POST", "/messages:editMarkup", nil, req, &out); err != nil {
		return nil, err
	}
	return &out, nil
}

// DeleteMessages: Deletes messages for everyone.
//
// The bot's own messages at any time; others' where the bot is an admin of the group or channel,
// and in a private chat (either side may). Messages the bot may not delete stay as they are; when
// none of them may be deleted the answer is `403 forbidden`. Unknown or already deleted seqs are
// ignored.
func (c *Client) DeleteMessages(ctx context.Context, req DeleteMessagesRequest) error {
	return c.call(ctx, "POST", "/messages:delete", nil, req, nil)
}

// ForwardMessages: Forwards messages with a forward header.
//
// Forwards messages of a chat the bot is in (and can see) into `chat_id`, in the order given; the
// rules of sending apply to the target (consent in private chats). `random_ids` (one per seq) make
// a retry return the first messages.
func (c *Client) ForwardMessages(ctx context.Context, req ForwardMessagesRequest) ([]Message, error) {
	var out []Message
	if err := c.call(ctx, "POST", "/messages:forward", nil, req, &out); err != nil {
		return nil, err
	}
	return out, nil
}

// CopyMessage: Posts a copy of a message without a forward header.
//
// Copies a message of a chat the bot is in (text or media, with its caption); `text` (with
// `entities` or `parse_mode`) replaces the text or caption.
func (c *Client) CopyMessage(ctx context.Context, req CopyMessageRequest) (*Message, error) {
	var out Message
	if err := c.call(ctx, "POST", "/messages:copy", nil, req, &out); err != nil {
		return nil, err
	}
	return &out, nil
}

// SetReaction: Sets or removes the bot's reaction on a message.
//
// One emoji per bot and message; an empty `emoji` removes the bot's reaction.
func (c *Client) SetReaction(ctx context.Context, req ReactRequest) error {
	return c.call(ctx, "POST", "/messages:react", nil, req, nil)
}

// PinMessage: Pins a message.
//
// Needs the permission to pin (admins; members where the group allows it; both sides of a private
// chat). Posts the "pinned" service message and counts as a send. Pinning a pinned message does
// nothing.
func (c *Client) PinMessage(ctx context.Context, req MessageRef) error {
	return c.call(ctx, "POST", "/messages:pin", nil, req, nil)
}

// UnpinMessage: Unpins a message.
//
// Needs the permission to pin. Unpinning a message that is not pinned does nothing.
func (c *Client) UnpinMessage(ctx context.Context, req MessageRef) error {
	return c.call(ctx, "POST", "/messages:unpin", nil, req, nil)
}

// SendMedia: Sends a photo, video, audio, voice message or document.
//
// Either upload the file (`multipart/form-data`: the file in the part `file`, `kind` and the other
// fields as form fields, `entities` as a JSON string) or send a file the bot can see again by
// `file_id` (JSON body). Uploads are checked like the app's: the content must match `kind`
// (photos: JPEG, PNG, GIF or WebP up to 20 MiB), metadata (EXIF/GPS) is stripped, photos get
// thumbnails, and the bot's storage quota applies; a file is at most 50 MiB. The same bytes
// uploaded again reuse the stored file. The server never downloads a URL for a bot. The text is
// the caption (up to 1024 characters).
func (c *Client) SendMedia(ctx context.Context, req SendMediaRequest) (*Message, error) {
	var out Message
	if err := c.call(ctx, "POST", "/messages:sendMedia", nil, req, &out); err != nil {
		return nil, err
	}
	return &out, nil
}

// SendAlbum: Sends 2 to 10 files as one album.
//
// Photos and videos mixed, or only documents, or only audio files. Each item names a `file_id` or,
// in a `multipart/form-data` request, the part holding its file (`attach`; `items` is then a JSON
// string form field). The messages share `grouped_id`. Upload rules as in `messages:sendMedia`;
// the whole request is at most 50 MiB.
func (c *Client) SendAlbum(ctx context.Context, req SendAlbumRequest) ([]Message, error) {
	var out []Message
	if err := c.call(ctx, "POST", "/messages:sendAlbum", nil, req, &out); err != nil {
		return nil, err
	}
	return out, nil
}

// SendBulk: Sends one message to many users.
//
// Queues one text message for the listed users, or for every user who started the bot (`all`).
// Each user gets it in their private chat with the bot; users without consent, who blocked the bot
// or were deleted are skipped. The job runs in the background at the bot tier's pace (new 2,
// default 10, verified 50, internal 200 messages per second, shared by the bot's jobs) and reaches
// each user at most once, also when the server restarts. Recipients in 24 hours are capped by tier
// (new 1,000, default 10,000, verified 1,000,000, internal none, restricted 0): over the cap the
// request answers `429 bulk_quota`. A bot has at most 5 unfinished jobs (`429 bulk_busy`). A job
// stops early when the bot is deleted (`bot_deleted`) or restricted (`bot_restricted`).
func (c *Client) SendBulk(ctx context.Context, req BulkRequest) (*BulkJob, error) {
	var out BulkJob
	if err := c.call(ctx, "POST", "/messages:bulk", nil, req, &out); err != nil {
		return nil, err
	}
	return &out, nil
}

// GetBulk: Progress of a bulk send.
func (c *Client) GetBulk(ctx context.Context, bulkID int64) (*BulkJob, error) {
	var out BulkJob
	if err := c.call(ctx, "GET", "/bulk/"+strconv.FormatInt(bulkID, 10), nil, nil, &out); err != nil {
		return nil, err
	}
	return &out, nil
}

// CancelBulk: Stops a bulk send.
//
// No new batch starts; the batch being sent (at most one second of the pace) still finishes.
// Messages already sent stay; a finished job is returned unchanged.
func (c *Client) CancelBulk(ctx context.Context, bulkID int64) (*BulkJob, error) {
	var out BulkJob
	if err := c.call(ctx, "DELETE", "/bulk/"+strconv.FormatInt(bulkID, 10), nil, nil, &out); err != nil {
		return nil, err
	}
	return &out, nil
}

// GetFile: A file the bot can see, with a download URL.
//
// The file of a message the bot can see (its own, or in a chat it is in, within the history it may
// see). `url` downloads it with a plain GET (Range supported) until `url_expires`, about an hour;
// it is bound to the bot and to that message, so deleting the message for everyone or the bot
// leaving the chat ends it. Ask again for a fresh URL.
func (c *Client) GetFile(ctx context.Context, fileID string) (*File, error) {
	var out File
	if err := c.call(ctx, "GET", "/files/"+url.PathEscape(fileID), nil, nil, &out); err != nil {
		return nil, err
	}
	return &out, nil
}

// GetUpdates: Long poll for updates.
//
// Returns pending updates with `update_id >= offset`, oldest first. A request with `offset`
// acknowledges every update below it, so pass the last `update_id + 1`; acknowledged updates are
// never returned again, even for a lower `offset`. When none are pending the request waits up to
// `timeout` seconds for the first one. Only one poll per bot runs at a time: a newer request ends
// the older one with `409 conflict`; while the bot has a webhook every poll answers `409
// conflict`, and setting a webhook ends a waiting poll with it. While the server restarts a
// waiting poll ends with an empty list and new polls answer `503 unavailable` with `retry_after`.
// Updates are kept 24 hours (callbacks 15 minutes). `update_id` strictly increases per bot.
func (c *Client) GetUpdates(ctx context.Context, params GetUpdatesParams) ([]Update, error) {
	var out []Update
	if err := c.call(ctx, "GET", "/updates", params.values(), nil, &out); err != nil {
		return nil, err
	}
	return out, nil
}

// SetWebhook: Receive updates at a webhook.
//
// From now on every update is POSTed to `url` (see the `update` webhook), a waiting long poll ends
// with `409 conflict` and further polls get it too. The URL must be `https` on port 443, 80 or
// 8443 and resolve to public addresses only; private, loopback, link-local, CGNAT, multicast,
// reserved and cloud metadata addresses are refused (`400 bad_request`), now and at every
// connection, so a name that later resolves to such an address (DNS rebinding) is not reached
// either. Redirects are not followed. Calling it again replaces every setting.
func (c *Client) SetWebhook(ctx context.Context, req SetWebhookRequest) error {
	return c.call(ctx, "PUT", "/webhook", nil, req, nil)
}

// DeleteWebhook: Go back to long poll.
//
// Removes the webhook (also when none is set). Pending updates stay for `GET /updates` unless
// `drop_pending`.
func (c *Client) DeleteWebhook(ctx context.Context, params DeleteWebhookParams) error {
	return c.call(ctx, "DELETE", "/webhook", params.values(), nil, nil)
}

// GetWebhook: Webhook settings and delivery state.
func (c *Client) GetWebhook(ctx context.Context) (*WebhookInfo, error) {
	var out WebhookInfo
	if err := c.call(ctx, "GET", "/webhook", nil, nil, &out); err != nil {
		return nil, err
	}
	return &out, nil
}

// AnswerCallback: Answers a button press.
//
// Answers the `callback` update `callback_id`, once. The user's client waits up to 10 seconds for
// the answer and shows `text` as a toast (or a dialog with `show_alert`); without an answer it
// shows that the bot is not responding. A press stays answerable for 15 minutes.
func (c *Client) AnswerCallback(ctx context.Context, callbackID string, req AnswerCallbackRequest) error {
	return c.call(ctx, "POST", "/callbacks/"+url.PathEscape(callbackID)+":answer", nil, req, nil)
}

// AnswerInlineQuery: Answers an inline query.
//
// Answers the `inline_query` update `inline_query_id`, once, within a minute (the user's client
// waits 10 seconds, then shows that the bot is not responding). Up to 50 results: an `article`
// posts `text` (with `entities` or `parse_mode`); a `photo`, `video` or `document` posts the bot's
// file `file_id` (a file the bot sent or can see) with an optional `caption`. Every result may
// carry an inline keyboard of URL buttons (no callback buttons: the posted message is the user's,
// in a chat the bot may not be in), and an article a `thumbnail_file_id` (a photo of the bot). The
// result the user picks is posted by the user, labelled "via" the bot. The answer is reused for
// the same query and offset for `cache_time` seconds (default 300, at most 3600), for every user
// unless `is_personal`. `next_offset` is sent back as `offset` when the user scrolls for more.
func (c *Client) AnswerInlineQuery(ctx context.Context, inlineQueryID string, req AnswerInlineQueryRequest) error {
	return c.call(ctx, "POST", "/inline/"+url.PathEscape(inlineQueryID)+":answer", nil, req, nil)
}

// SetCommands: Sets the command menu of one scope.
//
// Replaces the commands of `scope` (default `default`); an empty list removes the scope. Clients
// show the most specific list set: `group_admin` (group admins), then `group` or `private`, then
// `default`.
func (c *Client) SetCommands(ctx context.Context, req SetCommandsRequest) error {
	return c.call(ctx, "PUT", "/commands", nil, req, nil)
}

// GetChat: A chat the bot is a member of.
func (c *Client) GetChat(ctx context.Context, chatID int64) (*Chat, error) {
	var out Chat
	if err := c.call(ctx, "GET", "/chats/"+strconv.FormatInt(chatID, 10), nil, nil, &out); err != nil {
		return nil, err
	}
	return &out, nil
}

// EditChat: Changes the title and/or description of a group or channel.
//
// Needs the permission to change the info (admins; members where the group allows it). A new title
// posts the "title changed" service message.
func (c *Client) EditChat(ctx context.Context, chatID int64, req EditChatRequest) (*Chat, error) {
	var out Chat
	if err := c.call(ctx, "PATCH", "/chats/"+strconv.FormatInt(chatID, 10), nil, req, &out); err != nil {
		return nil, err
	}
	return &out, nil
}

// LeaveChat: The bot leaves a group or channel.
//
// Its pending updates of the chat are dropped; a `member_changed` with status `left` follows. A
// bot that owns the chat hands it to the longest-serving admin and cannot leave without one.
func (c *Client) LeaveChat(ctx context.Context, chatID int64) error {
	return c.call(ctx, "POST", "/chats/"+strconv.FormatInt(chatID, 10)+":leave", nil, nil, nil)
}

// GetChatAdmins: The owner and admins of a group or channel.
func (c *Client) GetChatAdmins(ctx context.Context, chatID int64) ([]ChatMember, error) {
	var out []ChatMember
	if err := c.call(ctx, "GET", "/chats/"+strconv.FormatInt(chatID, 10)+"/admins", nil, nil, &out); err != nil {
		return nil, err
	}
	return out, nil
}

// GetChatMember: One member of a group or channel.
//
// A current member, one who left or one who is banned; someone who never joined is `404`. In
// channels only admins see members.
func (c *Client) GetChatMember(ctx context.Context, chatID int64, userID int64) (*ChatMember, error) {
	var out ChatMember
	if err := c.call(ctx, "GET", "/chats/"+strconv.FormatInt(chatID, 10)+"/members/"+strconv.FormatInt(userID, 10), nil, nil, &out); err != nil {
		return nil, err
	}
	return &out, nil
}

// BanChatMember: Removes a member and bans them (admins).
//
// The user cannot come back (also not by invite link; the links they made stop working) until
// unbanned. Admins can be removed by the owner only.
func (c *Client) BanChatMember(ctx context.Context, chatID int64, userID int64) error {
	return c.call(ctx, "POST", "/chats/"+strconv.FormatInt(chatID, 10)+"/members/"+strconv.FormatInt(userID, 10)+":ban", nil, nil, nil)
}

// UnbanChatMember: Lifts a ban (admins); the user is not added back.
func (c *Client) UnbanChatMember(ctx context.Context, chatID int64, userID int64) error {
	return c.call(ctx, "POST", "/chats/"+strconv.FormatInt(chatID, 10)+"/members/"+strconv.FormatInt(userID, 10)+":unban", nil, nil, nil)
}

// RestrictChatMember: Sets what a member may do (admins).
//
// `permissions` is a bitmask; the member's rights are these bits within the group's defaults.
// Admins have every right (demote them first in the app).
func (c *Client) RestrictChatMember(ctx context.Context, chatID int64, userID int64, req RestrictRequest) error {
	return c.call(ctx, "POST", "/chats/"+strconv.FormatInt(chatID, 10)+"/members/"+strconv.FormatInt(userID, 10)+":restrict", nil, req, nil)
}

// SendChatAction: Shows "đang gõ…" (or sending a photo, …) for the bot.
//
// Users who have the chat open see the action for about 5 seconds or until the bot's next message;
// repeat it while working. The bot must be allowed to post there (consent in private chats). More
// than one action a second into one chat is merged. Note: the web app does not show actions yet;
// the API accepts them so bots need no change later.
func (c *Client) SendChatAction(ctx context.Context, chatID int64, req ChatActionRequest) error {
	return c.call(ctx, "POST", "/chats/"+strconv.FormatInt(chatID, 10)+"/actions", nil, req, nil)
}
